import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.DzGOF12C.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"논쟁의 발단","slug":"논쟁의-발단","link":"#논쟁의-발단","children":[]},{"level":2,"title":"주돈이의 「태극도설」","slug":"주돈이의-「태극도설」","link":"#주돈이의-「태극도설」","children":[]},{"level":2,"title":"진리는 어디에 있는가: 조한보 vs 이언적","slug":"진리는-어디에-있는가-조한보-vs-이언적","link":"#진리는-어디에-있는가-조한보-vs-이언적","children":[]},{"level":2,"title":"진리를 어떻게 얻을 것인가: 수양론의 쟁점","slug":"진리를-어떻게-얻을-것인가-수양론의-쟁점","link":"#진리를-어떻게-얻을-것인가-수양론의-쟁점","children":[]},{"level":2,"title":"적이감(寂而感)과 본연지묘(本然之妙)","slug":"적이감-寂而感-과-본연지묘-本然之妙","link":"#적이감-寂而感-과-본연지묘-本然之妙","children":[]},{"level":2,"title":"논쟁의 의의","slug":"논쟁의-의의","link":"#논쟁의-의의","children":[]}],"relativePath":"philosophy/Korean-Philosophy/08. 무극태극 논쟁.md","filePath":"philosophy/Korean-Philosophy/08. 무극태극 논쟁.md"}'),s={name:"philosophy/Korean-Philosophy/08. 무극태극 논쟁.md"};function l(a,t,i,u,g,h){return r(),e("div",null,[...t[0]||(t[0]=[n('<blockquote><p>이 강의는 시험 범위에서 제외된다고 표시되어 있으나(&quot;시험X&quot;), 조선 성리학 최초의 체계적 개념 논쟁이라는 위치를 갖는 만큼 흐름 파악을 위해 정리해둠.</p></blockquote><h2 id="논쟁의-발단" tabindex="-1">논쟁의 발단 <a class="header-anchor" href="#논쟁의-발단" aria-label="Permalink to &quot;논쟁의 발단&quot;">​</a></h2><p>1517년 「태극도설」해석을 둘러싸고 손숙돈과 조한보 사이에 편지 논쟁이 있었음(편지 원본은 소실). 당시 경주향교 교수였던 <strong>이언적(회재, 1491~1553)</strong>이 두 사람의 편지를 보고 양쪽 모두를 비판하는 글 「서망재망기당무극태극설후」를 지었고, 이를 본 <strong>조한보(호 망기당)</strong>가 반박 편지를 보내면서 이언적과 조한보 사이의 무극태극논쟁이 본격적으로 시작됨. 두 사람은 2년간 4통의 서신을 주고받았으며, 이는 조선 성리학 최초의 체계적 개념 논쟁으로 평가됨. 쟁점은 크게 둘 — ①<strong>진리는 어디에 있는가</strong>(세계관·진리관의 문제), ②<strong>진리는 어떻게 얻을 수 있는가</strong>(공부론·수양론의 문제).</p><p>이언적은 안강 외가에서 태어나 10세에 아버지를 잃고 외숙 손중돈(점필재 김종직의 문인)의 도움으로 수학, 27세 때 이 논쟁에 뛰어들었고 이후 이조·형조·예조판서를 거침. 을사사화 때는 좌찬성으로서 사림의 피해를 최소화하려 애썼으나 결과적으로 다수의 사림이 피해를 입었고, 만년에 양재역벽서사건에 연루되어 평안도 강계로 유배 가 그곳에서 사망함. 조한보는 성균관 유생 시절 동맹휴학에 연루되어 과거 응시 자격을 박탈당한 뒤, 벼슬길이 막힌 처지에서 도교·불교 사상에 심취해 있었던 인물로 추정됨.</p><h2 id="주돈이의-「태극도설」" tabindex="-1">주돈이의 「태극도설」 <a class="header-anchor" href="#주돈이의-「태극도설」" aria-label="Permalink to &quot;주돈이의 「태극도설」&quot;">​</a></h2><blockquote><p>&quot;무극이면서 태극이다(無極而太極). 태극이 움직여 양을 낳고, 움직임이 극에 달하면 고요해지며, 고요함이 음을 낳고, 고요함이 극에 달하면 다시 움직인다.&quot;</p></blockquote><p>한(漢)·당(唐)의 유학자들과 주돈이 자신도 태극을 <strong>기</strong>로 보았으나, 정이천과 주자는 태극을 <strong>리</strong>로 재해석함 — 주자는 &#39;極&#39;을 &quot;이 리(理)의 지극함을 이름한 것&quot;이라 풀이함. 문제는 여기서 &quot;<strong>무극</strong>&quot;이라는 말을 왜 굳이 덧붙였는가에 있다. 주자에 따르면 &quot;무극을 말하지 않으면 태극이 구체적인 한 가지 물건과 같아서 만 가지 변화의 근본이 되기에 부족하고, 태극을 말하지 않으면 무극이 공적(空寂)한 데 빠져서 만 가지 변화의 근본이 될 수 없다&quot;(『주자대전』) — 즉 태극(리)이 구체적 존재를 <strong>초월</strong>하면서도 동시에 구체적 존재에 <strong>내재</strong>한다는 양면성을 드러내기 위해 &#39;무극&#39;과 &#39;태극&#39;을 함께 말할 수밖에 없었다는 것.</p><h2 id="진리는-어디에-있는가-조한보-vs-이언적" tabindex="-1">진리는 어디에 있는가: 조한보 vs 이언적 <a class="header-anchor" href="#진리는-어디에-있는가-조한보-vs-이언적" aria-label="Permalink to &quot;진리는 어디에 있는가: 조한보 vs 이언적&quot;">​</a></h2><p><strong>조한보</strong>: &quot;태극은 곧 무극이다(太極卽無極).&quot; 태극의 본모습은 무극이며, 무극은 우주의 시원인 &#39;태허&#39;에 해당하고 태허의 본체는 &#39;적멸(寂滅)&#39;하다. 반면 현상세계는 무상(無常)하다. 따라서 영원불변한 보편적 진리인 태극은 가변적이고 무상한 현상계가 아니라 그것을 초월한 세계에 있다.</p><p><strong>이언적</strong>: &quot;무극이지만 사실은 태극이다(無極而太極).&quot; 강조점을 태극에 둠으로써 결코 공적한 상태로 떨어지지 않게 함 — 그렇게 되면 지극히 가깝고 실제적인 상황, 즉 일상생활 속에서도 태극(리)을 구할 수 있다. 태극은 초월 세계에도 존재하지만, 동시에 우리가 살아가는 구체적인 일상의 삶 속에도 있다는 것.</p><p>이언적은 조한보의 관점을 다음과 같이 비판한다 — &quot;손숙돈에 대한 조한보의 답서를 볼 것 같으면, 얼른 보아서 주돈이의 논지에 근거한 것 같지만, 그 논의가 지나치게 고원(현실성이 결여됨)하다… 그렇기 때문에 우리 유가의 학설에 위배된다.&quot;(「서망재망기당무극태극설후」)</p><h2 id="진리를-어떻게-얻을-것인가-수양론의-쟁점" tabindex="-1">진리를 어떻게 얻을 것인가: 수양론의 쟁점 <a class="header-anchor" href="#진리를-어떻게-얻을-것인가-수양론의-쟁점" aria-label="Permalink to &quot;진리를 어떻게 얻을 것인가: 수양론의 쟁점&quot;">​</a></h2><p><strong>조한보</strong>: &#39;<strong>존심상달</strong>(存心上達)&#39; — 마음을 보존하여 단번에 천리를 깨우침. &#39;<strong>유심어무극지진</strong>(遊心於無極之眞)&#39; — 마음을 무극의 참된 경지에서 노닐게 함.</p><p><strong>이언적</strong>: &#39;존심상달&#39;은 본체의 체득을 강조하는 표현으로, 사실상 <strong>돈오상달(頓悟上達)</strong>, 즉 불가(佛家)의 수행 방법이다. 유가의 전통적 수행 방법은 &#39;<strong>하학이상달</strong>(下學而上達)&#39; — 아래로 사람의 일을 배워야 자연히 위로 하늘의 이치에 통달하게 된다는 것. &quot;만일 아래로 사람의 일을 배우는 공부 없이 바로 하늘의 이치에 통달하려 한다면, 이것은 불교의 깨달음에 대한 주장이니 어찌 숨길 수 있겠습니까?&quot; 하늘의 이치가 사람의 일과 떨어진 것이 아니므로, 도는 고원한 곳에 있는 것이 아니라 일상생활 속에서 닦아야 한다는 것이 이언적의 결론이다. (이에 조한보는 &quot;하학상달은 어린아이나 처음 공부하는 사람을 가리킨 것이지 호걸 같은 선비는 이와 같지 않다&quot;고 재반박함.)</p><h2 id="적이감-寂而感-과-본연지묘-本然之妙" tabindex="-1">적이감(寂而感)과 본연지묘(本然之妙) <a class="header-anchor" href="#적이감-寂而感-과-본연지묘-本然之妙" aria-label="Permalink to &quot;적이감(寂而感)과 본연지묘(本然之妙)&quot;">​</a></h2><p>이언적은 마음(心)을 <strong>기 속에 태극(리)이 부여된 것</strong>(심=기+리)으로 규정한다. &quot;사람의 마음은 천지에 음양이 있는 것과 같아서 그곳에 &#39;태극의 진리&#39;가 존재한다. 외물의 자극을 받기 전에는 담연허정(湛然虛靜)하여 아무것도 없는 것 같으니, 이것이 바로 &#39;무성무취지묘(無聲無臭之妙)&#39;이며 보내주신 편지에서 말한 &#39;적(寂)&#39;입니다. 그러나 지극히 허·적한 가운데 이 리가 혼연히 모두 갖추어져 있기에 &#39;감(感)&#39;하여 마침내 천하의 일에 통하는 것입니다. 만일 적(寂)한 데다가 멸(滅)하기까지 하다면 이것은 적연한 목석일 뿐이니 천하의 대본이 되는 근거가 어디에 있습니까?&quot; — 즉 이언적은 조한보가 말하는 &#39;적멸&#39;과 자신이 말하는 &#39;적감(寂感)&#39;을 구별함으로써, 마음의 고요함(未發)이 아무것도 없는 죽은 상태(적멸)가 아니라 그 안에 리가 온전히 갖추어져 외물에 감응할 수 있는 살아있는 상태(적감)임을 강조한다.</p><p>나아가 성(性)을 <strong>본연지체</strong>(本然之體, 희로애락이 발하기 전 혼연한 마음의 본래 상태)와 <strong>본연지묘</strong>(本然之妙, 외부 자극에 감응하여 희로애락이 발현되되 절도에 맞는 상태)로 나누는데, 이러한 리의 &#39;본연의 체&#39;와 &#39;신묘한 작용&#39;이라는 구도는 훗날 <strong>이황</strong>이 &quot;리무위설&quot;(리 본연의 체)과 &quot;리자도&quot;(리의 신묘한 작용)를 함께 말하는 방식으로 계승됨.</p><h2 id="논쟁의-의의" tabindex="-1">논쟁의 의의 <a class="header-anchor" href="#논쟁의-의의" aria-label="Permalink to &quot;논쟁의 의의&quot;">​</a></h2><ol><li>조선 성리학 최초의 본격적 철학 논쟁으로 주자학의 정통성을 확립함 — &#39;태극&#39; 개념을 정통 주자학적 관점에서 처음 본격적으로 논변하고, 주자의 &#39;리일분수&#39; 이론을 조선에서 처음 제창함. 이후 수많은 성리학 논쟁이 이 논쟁을 뒤이어 발생함.</li><li>유학에 노장·불교 사상이 혼입되는 것을 배척함 — &#39;무극적멸&#39;을 불교의 적멸·공 사상이라 비판하고, &#39;존심상달&#39;을 불교의 돈오설이라 비판하고, 태극을 &#39;태허&#39;로 보는 관점을 도가의 허무·무 사상이라 비판함.</li><li>주자학의 한국적 특성을 이루는 토대를 마련함 — 태극을 리이자 도덕적 본체로 해석하여 심성론적 실천 문제에 천착하는 방향(태극⇒리⇒능동적 도덕성)이 훗날 <strong>이황</strong>에게로 전달됨.</li></ol>',19)])])}const c=o(s,[["render",l]]);export{q as __pageData,c as default};
